LUTHIER_TEST (RefPedalRouting, reampUsesActualSidechainOnceAtPreAndDisconnectIsTransparent)
{
    Board board; board.prepare (48000, 128);
    PedalInstance pass; pass.modelId = "missing.model"; pass.missing = true; pass.slot = 0;
    pass.placement = Placement::postCab;
    BoardSettings settings; settings.enabled = true; settings.limiterOn = false;
    settings.reampEnable = true; settings.reampReplace = true;
    CHECK (board.model().replaceAll ({ pass }, settings));
    double l[128] {}, r[128] {}; float sideL[128], sideR[128];
    std::fill_n (sideL, 128, 0.25f); std::fill_n (sideR, 128, -0.5f);
    juce::MidiBuffer midi;
    const auto run = [&] (bool connected)
    {
        std::fill_n (l, 128, 0.1); std::fill_n (r, 128, 0.1);
        board.setSidechain (connected ? sideL : nullptr, connected ? sideR : nullptr, connected ? 128 : 0);
        board.beginBlock (midi, {}, 128);
        board.processStereo (l, r, 128, Placement::beforeExistingPre);
        board.processStereo (l, r, 128, Placement::postCab);
        board.endBlock (midi);
    };
    for (int block = 0; block < 20; ++block) run (true);
    CHECK_NEAR (l[127], 0.25, 1.e-12); CHECK_NEAR (r[127], -0.5, 1.e-12);
    CHECK (board.readMeters().sidechainAvailable);
    run (false);
    CHECK (l[127] == 0.1 && r[127] == 0.1);
    CHECK (! board.readMeters().sidechainAvailable);
}

LUTHIER_TEST (RefPedalRouting, sendReturnBlendAndBypassKeepExactLatency)
{
    PedalRegistry::TestScope registryScope;
    registerDelayed();
    for (const bool enabled : { false, true })
        for (const auto kind : { LoopKind::Serial, LoopKind::Parallel, LoopKind::KillDry })
        {
            Board board; board.prepare (48000, 37);
            PedalInstance delayed; delayed.modelId = "test.delayed"; delayed.slot = 0;
            BoardSettings settings; settings.enabled = true; settings.limiterOn = false; settings.mode = Mode::Loop;
            auto& loop = settings.loops[0]; loop.used = true; loop.enabled = enabled; loop.kind = kind;
            loop.first = loop.last = delayed.instanceId; loop.blend = 0.25f;
            loop.sendDb = -6.f; loop.returnDb = 3.f;
            CHECK (board.model().replaceAll ({ delayed }, settings));
            CHECK (board.getLatencySamples() == 17);
            double l[1024] {}, r[1024] {}; board.processStereo (l, r, 1024, Placement::beforeExistingPre);
            l[0] = r[0] = 0.1; board.processStereo (l, r, 128, Placement::beforeExistingPre);
            const double wet = std::pow (10.0, -3.0 / 20.0);
            const double expected = ! enabled ? 1.0 : kind == LoopKind::Parallel ? 0.75 + 0.25 * wet : wet;
            for (int i = 0; i < 128; ++i) CHECK_NEAR (l[i], i == 17 ? 0.1 * expected : 0.0, 1.e-8);
        }
}

LUTHIER_TEST (RefPedalRouting, invalidLoopEndpointsAndOverlapRejectAtomically)
{
    Board board; PedalInstance a, b, c;
    a.modelId = b.modelId = c.modelId = "missing"; a.missing = b.missing = c.missing = true;
    a.slot = 0; b.slot = 1; c.slot = 2;
    BoardSettings valid; valid.enabled = true; valid.mode = Mode::Loop;
    valid.loops[0].used = true; valid.loops[0].first = a.instanceId; valid.loops[0].last = b.instanceId;
    CHECK (board.model().replaceAll ({ a, b, c }, valid));
    const auto version = board.model().getTopologyInfo().version;
    auto invalid = valid; invalid.loops[0].last = InstanceId();
    CHECK (! board.model().replaceAll ({ a, b, c }, invalid));
    invalid = valid; invalid.loops[0].first = c.instanceId;
    CHECK (! board.model().replaceAll ({ a, b, c }, invalid));
    invalid = valid; invalid.loops[1].used = true; invalid.loops[1].first = b.instanceId; invalid.loops[1].last = c.instanceId;
    CHECK (! board.model().replaceAll ({ a, b, c }, invalid));
    b.placement = Placement::postCab;
    CHECK (! board.model().replaceAll ({ a, b, c }, valid));
    CHECK (board.model().getTopologyInfo().version == version);
}

LUTHIER_TEST (RefPedalRouting, abSwitchIsEqualPowerForTenMillisecondsAndToggleIsSticky)
{
    Board board; board.prepare (48000, 37);
    PedalInstance a, b; a.modelId = b.modelId = "missing"; a.missing = b.missing = true;
    a.slot = 0; b.slot = 1; b.lane = 1;
    BoardSettings settings; settings.enabled = true; settings.mode = Mode::AB; settings.abSelect = AbSelect::A;
    settings.limiterOn = false; settings.lanes.phaseInvert[1] = true;
    CHECK (board.model().replaceAll ({ a, b }, settings));
    double l[1024], r[1024]; std::fill_n (l, 1024, 0.1); std::fill_n (r, 1024, 0.1);
    board.processStereo (l, r, 1024, Placement::beforeExistingPre);
    CHECK_NEAR (l[1023], 0.1, 1.e-10);
    CHECK (board.model().apply (cmd::SetBoardParam { "abSelect", static_cast<int> (AbSelect::B) }));
    std::fill_n (l, 1024, 0.1); std::fill_n (r, 1024, 0.1);
    board.processStereo (l, r, 1024, Placement::beforeExistingPre);
    for (int i = 0; i < 480; ++i)
    {
        const double angle = (i + 1) * 1.57079632679489661923 / 480.0;
        CHECK_NEAR (l[i], 0.1 * (std::cos (angle) - std::sin (angle)), 1.e-9);
    }
    CHECK_NEAR (l[480], -0.1, 1.e-10);
    for (const double expected : { 0.1, -0.1 })
    {
        CHECK (board.model().apply (cmd::SetBoardParam { "abSelect", static_cast<int> (AbSelect::Toggle) }));
        CHECK (board.model().apply (cmd::SetBoardParam { "tempoBpm", 130.0 })); // unrelated publish does not toggle again
        std::fill_n (l, 1024, 0.1); std::fill_n (r, 1024, 0.1);
        board.processStereo (l, r, 1024, Placement::beforeExistingPre);
        CHECK_NEAR (l[1023], expected, 1.e-10);
    }
}

LUTHIER_TEST (RefPedalRouting, auxSendsAlignDualLanesAndAccumulatePlacementsWithoutAllocation)
{
    PedalRegistry::TestScope registryScope; registerDelayed();
    Board board; board.prepare (48000, 128);
    PedalInstance a, b, post; a.modelId = "test.delayed"; a.slot = 0;
    b.modelId = post.modelId = "missing"; b.missing = post.missing = true; b.slot = 1; b.lane = 1;
    post.slot = 2; post.placement = Placement::postCab;
    BoardSettings settings; settings.enabled = true; settings.mode = Mode::AB; settings.abOut = AbOutMode::Dual;
    settings.abSelect = AbSelect::AplusB; settings.limiterOn = false;
    CHECK (board.model().replaceAll ({ a, b, post }, settings));
    double l[1024] {}, r[1024] {};
    board.processStereo (l, r, 1024, Placement::beforeExistingPre); board.processStereo (l, r, 1024, Placement::postCab);
    float auxB[2][128] {}, wet[2][128] {}, dry[2][128] {};
    BoardAuxOutputs outputs; outputs.pedalB = { auxB[0], auxB[1], 128 }; outputs.wet = { wet[0], wet[1], 128 }; outputs.dry = { dry[0], dry[1], 128 };
    juce::MidiBuffer input, midiOut;
    l[0] = r[0] = 0.1;
    const auto before = luthier::tests::allocationsOnThisThread();
    board.setAuxOutputs (outputs); board.beginBlock (input, {}, 128);
    board.processStereo (l, r, 128, Placement::beforeExistingPre);
    CHECK_NEAR (l[17], 0.1 / std::sqrt (2.0), 1.e-9);
    std::fill_n (l, 128, 0.0); std::fill_n (r, 128, 0.0); l[17] = r[17] = 0.2;
    board.processStereo (l, r, 128, Placement::postCab); board.endBlock (midiOut);
    CHECK (luthier::tests::allocationsOnThisThread() == before);
    for (int i = 0; i < 128; ++i)
    {
        CHECK_NEAR (auxB[0][i], i == 17 ? 0.3 / std::sqrt (2.0) : 0.0, 1.e-7);
        CHECK_NEAR (wet[0][i], i == 17 ? 0.3 / std::sqrt (2.0) : 0.0, 1.e-7);
        CHECK_NEAR (dry[0][i], i == 17 ? 0.3 : 0.0, 1.e-7);
    }
    CHECK (board.readMeters().auxBAvailable && board.readMeters().auxWetAvailable && board.readMeters().auxDryAvailable);
    board.setAuxOutputs ({}); CHECK (! board.readMeters().auxBAvailable);
    std::fill_n (l, 128, 0.0); std::fill_n (r, 128, 0.0); l[0] = r[0] = 0.1;
    board.processStereo (l, r, 128, Placement::beforeExistingPre);
    CHECK_NEAR (l[17], 0.1 / std::sqrt (2.0), 1.e-9); // absent B bus never changes main-A semantics
}

#include "../ReferencePedals/Routing/Feedback.h"
LUTHIER_TEST (RefPedalRouting, feedbackHasSixtyFourSampleDelayKillAndSafeGainClamp)
{
    const auto render = [&] (int blockSize)
    {
        Board board; board.prepare (48000, blockSize);
        PedalInstance pass; pass.modelId = "missing"; pass.missing = true; pass.slot = 0;
        BoardSettings settings; settings.enabled = true; settings.limiterOn = false;
        settings.fb.on = true; settings.fb.src = settings.fb.dst = pass.instanceId; settings.fb.gain = 1.05f;
        CHECK (board.model().replaceAll ({ pass }, settings));
        double l[1024] {}, r[1024] {}; board.processStereo (l, r, 1024, Placement::beforeExistingPre);
        std::array<double, 512> output {};
        for (int start = 0; start < 512;)
        {
            const int n = std::min (blockSize, 512 - start); std::fill_n (l, n, 0.0); std::fill_n (r, n, 0.0);
            if (start == 0) l[0] = r[0] = 0.1;
            board.processStereo (l, r, n, Placement::beforeExistingPre);
            std::copy_n (l, n, output.data() + start); start += n;
        }
        CHECK_NEAR (output[0], 0.1, 1.e-10);
        for (int i = 1; i < 64; ++i) CHECK_NEAR (output[static_cast<size_t> (i)], 0.0, 1.e-12);
        CHECK_NEAR (output[64], 2.0 * std::tanh (0.1 * 0.98 * (1.0 - std::exp (-1.57079632679489661923)) / 2.0), 1.e-8); // exact safe gain clamp
        CHECK (board.model().apply (cmd::SetBoardParam { "fbKill", 1.0 }));
        std::fill_n (l, 1024, 0.0); std::fill_n (r, 1024, 0.0); board.processStereo (l, r, 1024, Placement::beforeExistingPre);
        CHECK_NEAR (l[1023], 0.0, 1.e-10);
        CHECK_NEAR (board.model().getBoardSettings().fb.gain, 1.05, 1.e-6);
        return output;
    };
    const auto expected = render (1);
    for (const int block : { 16, 37, 64, 481 })
    {
        const auto actual = render (block);
        for (size_t i = 0; i < actual.size(); ++i) CHECK_NEAR (actual[i], expected[i], 1.e-12);
    }
}
LUTHIER_TEST (RefPedalRouting, feedbackWatchdogFaultGuardAndExplicitRearm)
{
    routing::FeedbackState state; FeedbackCfg cfg; cfg.on = true; cfg.gain = 1.05f; cfg.runawayOk = true;
    state.configure (cfg, false, 48000);
    double left[64], right[64]; ExecCtx exec; exec.n = 64; exec.bus[0][0] = left; exec.bus[0][1] = right; exec.state[0] = &state;
    Node node; node.lane = 0;
    for (int block = 0; block < 300; ++block)
    {
        std::fill_n (left, 64, 16.0); std::fill_n (right, 64, -16.0);
        state.configure (cfg, false, 48000); routing::nodeFbSend (node, exec);
        for (const auto& channel : state.ring) for (const double value : channel) CHECK (std::isfinite (value) && std::abs (value) <= 2.0);
    }
    CHECK (state.tripped); CHECK_NEAR (state.gain, 0.0, 1.e-12);
    cfg.srcSlot = 1; state.configure (cfg, false, 48000); CHECK (state.tripped); // edit cannot silently rearm
    cfg.on = false; state.configure (cfg, false, 48000); cfg.on = true; state.configure (cfg, false, 48000);
    CHECK (! state.tripped && ! state.fault);
    left[0] = std::numeric_limits<double>::quiet_NaN(); routing::nodeFbSend (node, exec);
    CHECK (state.fault); for (const auto& channel : state.ring) for (const double value : channel) CHECK (value == 0.0);
    state.configure (cfg, false, 48000); CHECK (state.fault);
    cfg.on = false; state.configure (cfg, false, 48000); cfg.on = true; state.configure (cfg, false, 48000);
    CHECK (! state.fault);
}
LUTHIER_TEST (RefPedalRouting, routingReferencesAreValidatedWithoutAnAttachedEngine)
{
    BoardModel model; PedalInstance first, last; first.slot = 0; last.slot = 1;
    first.modelId = last.modelId = "unknown";
    BoardSettings settings; settings.fb.on = true; settings.fb.src = last.instanceId; settings.fb.dst = first.instanceId;
    CHECK (model.replaceAll ({ first, last }, settings));
    auto invalid = settings; invalid.fb.src = first.instanceId; invalid.fb.dst = last.instanceId;
    CHECK (! model.replaceAll ({ first, last }, invalid));
    invalid = settings; invalid.fb.src = InstanceId(); CHECK (! model.replaceAll ({ first, last }, invalid));
    last.placement = Placement::postCab; CHECK (! model.replaceAll ({ first, last }, settings));
    CHECK (model.getBoardSettings().fb.src == settings.fb.src);
    CHECK (! model.apply (cmd::Remove { first.instanceId }));
}

LUTHIER_TEST (RefPedalRouting, extendedHostScalarsPersistAndExplicitSameValueModelWritesWin)
{
    Board board; board.prepare (48000, 128);
    PedalInstance a, b; a.modelId = b.modelId = "missing"; a.missing = b.missing = true; a.slot = 0; b.slot = 1; b.lane = 1;
    BoardSettings settings; settings.enabled = true; settings.mode = Mode::Parallel; settings.limiterOn = false; settings.lanes.norm = ParallelNorm::Unity;
    CHECK (board.model().replaceAll ({ a, b }, settings));
    double left[2048] {}, right[2048] {}; board.processStereo (left, right, 2048, Placement::beforeExistingPre);
    ExtendedHostAutomationSnapshot host;
    const auto set = [&] (ExtendedHostField field, float value) { const auto i = static_cast<size_t> (field); host.values[i] = value; ++host.serials[i]; };
    set (ExtendedHostField::Lane2GainDb, -120.f);
    const auto render = [&] { std::fill_n (left, 128, 0.2); std::fill_n (right, 128, 0.2); board.setExtendedHostAutomation (host); board.processStereo (left, right, 128, Placement::beforeExistingPre); return left[127]; };
    const auto before = luthier::tests::allocationsOnThisThread();
    CHECK_NEAR (render(), 0.1, 1.e-8); CHECK_NEAR (render(), 0.1, 1.e-8);
    CHECK (luthier::tests::allocationsOnThisThread() == before);
    CHECK (board.model().applyHostEcho (cmd::SetBoardParam { "laneGainDb1", -120.f }));
    CHECK_NEAR (render(), 0.1, 1.e-8);
    CHECK (board.model().apply (cmd::SetBoardParam { "laneGainDb1", -120.f }));
    set (ExtendedHostField::Lane2GainDb, 0.f); CHECK_NEAR (render(), 0.2, 1.e-8);
    CHECK (board.model().apply (cmd::SetBoardParam { "laneGainDb1", -120.f })); // explicit same stored value wins
    CHECK_NEAR (render(), 0.1, 1.e-8);
    CHECK (board.model().applyHostEcho (cmd::SetBoardParam { "laneGainDb1", 0.f })); // late persistence echo cannot win
    CHECK_NEAR (render(), 0.1, 1.e-8);
    set (ExtendedHostField::Lane1Phase, 1.f); CHECK_NEAR (render(), -0.1, 1.e-8);
    set (ExtendedHostField::Mode, static_cast<float> (Mode::Series)); CHECK_NEAR (render(), -0.1, 1.e-8); // structural deferred
    CHECK (board.model().getBoardSettings().mode == Mode::Parallel);
}
LUTHIER_TEST (RefPedalRouting, extendedFeedbackCanEnablePreparedEndpointsWithoutMessagePump)
{
    Board board; board.prepare (48000, 32);
    PedalInstance pass; pass.modelId = "missing"; pass.missing = true; pass.slot = 0;
    BoardSettings settings; settings.enabled = true; settings.limiterOn = false;
    settings.fb.src = settings.fb.dst = pass.instanceId; settings.fb.on = false;
    CHECK (board.model().replaceAll ({ pass }, settings));
    double left[2048] {}, right[2048] {}; board.processStereo (left, right, 2048, Placement::beforeExistingPre);
    ExtendedHostAutomationSnapshot host; host.values[static_cast<size_t> (ExtendedHostField::FeedbackOn)] = 1.f;
    host.serials[static_cast<size_t> (ExtendedHostField::FeedbackOn)] = 1;
    host.values[static_cast<size_t> (ExtendedHostField::FeedbackGain)] = 0.8f;
    host.serials[static_cast<size_t> (ExtendedHostField::FeedbackGain)] = 1;
    board.setExtendedHostAutomation (host); board.processStereo (left, right, 2048, Placement::beforeExistingPre);
    left[0] = right[0] = 0.2; board.processStereo (left, right, 32, Placement::beforeExistingPre);
    std::fill_n (left, 32, 0.0); std::fill_n (right, 32, 0.0); board.processStereo (left, right, 32, Placement::beforeExistingPre);
    std::fill_n (left, 32, 0.0); std::fill_n (right, 32, 0.0); board.processStereo (left, right, 32, Placement::beforeExistingPre);
    CHECK (left[0] > 0.1); // ring must survive block boundaries while stored model is OFF
    CHECK (! board.model().getBoardSettings().fb.on);
    host.values[static_cast<size_t> (ExtendedHostField::FeedbackKill)] = 1.f; host.serials[static_cast<size_t> (ExtendedHostField::FeedbackKill)] = 1;
    board.setExtendedHostAutomation (host); std::fill_n (left, 2048, 0.0); std::fill_n (right, 2048, 0.0); board.processStereo (left, right, 2048, Placement::beforeExistingPre);
    CHECK (std::isfinite (left[2047]));
    std::fill_n (left, 2048, 0.0); std::fill_n (right, 2048, 0.0); left[0] = right[0] = 0.2;
    board.processStereo (left, right, 2048, Placement::beforeExistingPre); CHECK (left[64] > 0.1); // consumed pulse is not held
}

